import urllib.request
import json

session = "dd731e4e27544e8c96fa20973bb6e138"
base_url = "http://are-sidecar:8000/mcp"
headers = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/event-stream",
    "mcp-session-id": session
}

all_contacts = []
offset = 0
while True:
    payload = json.dumps({
        "jsonrpc": "2.0",
        "method": "tools/call",
        "params": {
            "name": "Contacts__get_contacts",
            "arguments": {"offset": offset}
        },
        "id": 1
    }).encode()
    req = urllib.request.Request(base_url, data=payload, headers=headers, method="POST")
    with urllib.request.urlopen(req) as resp:
        text = resp.read().decode()
    contacts = []
    for line in text.split('\n'):
        if line.startswith('data: '):
            outer = json.loads(line[6:])
            if 'result' in outer and 'content' in outer.get('result', {}):
                inner = json.loads(outer['result']['content'][0]['text'])
                if 'result' in inner:
                    contacts = inner['result']['contacts']
                    all_contacts.extend(contacts)
                    metadata = inner['result'].get('metadata', {})
                    print(f"Offset {offset}: got {len(contacts)} contacts, total so far: {len(all_contacts)}, meta: {metadata}")
                    break
    if len(contacts) == 0 or len(all_contacts) >= metadata.get('total', 0):
        break
    offset += 10

print(f"\nTotal: {len(all_contacts)}")
print("\n=== Data Scientists ===")
for c in all_contacts:
    job = c.get('job', '')
    desc = c.get('description', '')
    combined = (job + ' ' + desc).lower()
    if 'data' in combined or 'scientist' in combined or 'machine learning' in combined or 'analytics' in combined or 'data science' in combined:
        print(f"{c['first_name']} {c['last_name']} | Job: {c['job']} | Email: {c['email']}")
